// Adds the "generated" header to src/api/schema.d.ts after openapi-typescript runs.
import { readFileSync, writeFileSync } from "node:fs";

const file = process.argv[2];
if (!file) throw new Error("usage: prepend-generated-header.mjs <file>");
const header =
  "// GENERATED by `pnpm api:types` from openapi/openapi.json. Do not edit by hand.\n\n";
const body = readFileSync(file, "utf8");
if (!body.startsWith(header)) writeFileSync(file, header + body);
